bool isElegant(const string& s) {
    // 首字符必须是大写，末字符必须是小写
    if (s.empty() || !(s[0] >= 'A' && s[0] <= 'Z'))
        return false;
    if (!(s.back() >= 'a' && s.back() <= 'z'))
        return false;

    int lowerMask = 0, upperMask = 0;
    for (char ch : s) {
        if (ch >= 'a' && ch <= 'z') {
            int idx = ch - 'a';
            if (upperMask & (1 << idx)) // 同一字母的大写已出现，冲突
                return false;
            lowerMask |= (1 << idx);
        } else if (ch >= 'A' && ch <= 'Z') {
            int idx = ch - 'A';
            if (lowerMask & (1 << idx)) // 同一字母的小写已出现，冲突
                return false;
            upperMask |= (1 << idx);
        }
        // 字符串仅由字母组成，无需处理其他情况
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
